select c.column_name,c.data_type,c.is_nullable from information_schema.columns c where c.table_schema='public' and c.table_name='receivables' and c.column_name='distributor_id';
select con.conname,pg_get_constraintdef(con.oid) as definition from pg_constraint con where con.conrelid='public.receivables'::regclass and con.conname='receivables_distributor_id_fkey';
select indexname,indexdef from pg_indexes where schemaname='public' and tablename='receivables' and indexname in ('receivables_distributor_id_lookup_idx','receivables_distributor_bill_reference_uidx') order by indexname;
select jsonb_build_object('receivable_rows',(select count(*) from public.receivables),'receivable_bill_total',(select coalesce(sum(bill_amount),0) from public.receivables),'payment_rows',(select count(*) from public.receivable_payments),'effective_confirmed_collected',(select coalesce(sum(amount),0) from public.receivable_payments where verification_status='confirmed' and reversed_at is null),'effective_outstanding',(select coalesce(sum(outstanding_amount),0) from public.receivables_financial_read_v1 where lifecycle_status<>'cancelled')) as distributor_receivable_link_postcheck;
